[
  {
    "id": "cart_required_from_start",
    "text": "Customers are obliged to obtain a shopping cart before completing their shopping trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_main_aisle_without_cart",
    "text": "Customers are prohibited from entering the main shopping aisle at row y=6 without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "or": [
              "at(1,6)",
              "at(2,6)",
              "at(3,6)",
              "at(4,6)",
              "at(5,6)",
              "at(6,6)",
              "at(7,6)",
              "at(8,6)",
              "at(9,6)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_item_interact_without_cart",
    "text": "Customers are prohibited from interacting with the shelf at location (9,6) unless they have a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(9,6)",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "Customers are prohibited from leaving the store without a shopping cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "take_cart_at_cart_bay",
    "text": "Customers who reach the cart bay at location (1,7) are obliged to take a cart.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "at(1,7)",
      "discharge": "hasCart"
    }
  },
  {
    "id": "cart_one_way_no_west",
    "text": "Customers pushing a cart are prohibited from moving west, as if cart traffic is one-way.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "W"
        ]
      }
    }
  },
  {
    "id": "no_cart_east_on_front_row",
    "text": "Customers with carts are prohibited from moving east along the front row y=7 before the checkout corridor.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "E",
          {
            "or": [
              "at(1,7)",
              "at(2,7)",
              "at(3,7)",
              "at(4,7)",
              "at(5,7)",
              "at(6,7)",
              "at(7,7)",
              "at(8,7)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "exit_after_shelf_interaction",
    "text": "After interacting with the shelf at location (9,6), customers are obliged to proceed to the exit.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(9,6)",
          "INTERACT"
        ]
      },
      "discharge": "EXIT"
    }
  }
]
